#!/usr/bin/env node
/**
 * Build-time embed of the sizer's vendored `src/matchers/ignorefile.txt`
 * into a TS constant.
 *
 * Why we embed instead of reading at runtime: the Bun-compiled single-file
 * binary has no readable filesystem layout to discover the original path,
 * Embedding at build time keeps the npm-style JS output and the compiled
 * binary on the same pattern set without needing runtime filesystem discovery.
 *
 * Output: `src/generated/ignoreFileContent.ts`. Generated; do not edit by
 * hand. Re-runs on every build via the package's `prebuild` script.
 */

import { readFileSync, writeFileSync, mkdirSync, statSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const PACKAGE_ROOT = resolve(__dirname, '..');
const SOURCE = resolve(PACKAGE_ROOT, 'src', 'matchers', 'ignorefile.txt');
const OUTPUT = resolve(PACKAGE_ROOT, 'src', 'generated', 'ignoreFileContent.ts');

function main() {
  const stat = statSync(SOURCE, { throwIfNoEntry: false });
  if (!stat || !stat.isFile()) {
    throw new Error(
      `embed-ignorefile: source not found at ${SOURCE}.\n` +
        `Expected to find packages/sizer-cli/src/matchers/ignorefile.txt.`
    );
  }

  const content = readFileSync(SOURCE, 'utf8');
  if (content.length <= 100) {
    throw new Error(
      `embed-ignorefile: source at ${SOURCE} looks too small (${content.length} chars).`
    );
  }

  // Compute a non-cryptographic byte-length stamp so a reviewer can see at a
  // glance whether this file was regenerated against the latest shared copy.
  const bytes = Buffer.byteLength(content, 'utf8');

  const banner =
    `// AUTO-GENERATED by scripts/embed-ignorefile.mjs at build time.\n` +
    `// Source:  src/matchers/ignorefile.txt (${bytes} bytes)\n` +
    `// Do NOT edit by hand — re-run \`npm run embed-ignorefile\` (or any build).\n`;

  const body =
    `\n/** Verbatim contents of the global ignorefile.txt at build time. */\n` +
    `export const GLOBAL_IGNORE_FILE_CONTENT: string = ${JSON.stringify(content)};\n` +
    `\n/** Bytes embedded — handy for a fast "did the embed run?" smoke check. */\n` +
    `export const GLOBAL_IGNORE_FILE_BYTES: number = ${bytes};\n`;

  mkdirSync(dirname(OUTPUT), { recursive: true });
  writeFileSync(OUTPUT, banner + body, 'utf8');

  // eslint-disable-next-line no-console
  console.log(
    `embed-ignorefile: wrote ${OUTPUT} (${bytes} bytes embedded from vendored ignorefile)`
  );
}

main();
